def merge_gap(a: list[int], b: list[int]) -> None:
    n, m = len(a), len(b)
    total = n + m

    def get(idx: int) -> int:
        return a[idx] if idx < n else b[idx - n]

    def put(idx: int, val: int) -> None:
        if idx < n:
            a[idx] = val
        else:
            b[idx - n] = val

    gap = (total + 1) // 2
    while gap > 0:
        i = 0
        while i + gap < total:
            if get(i) > get(i + gap):
                x, y = get(i), get(i + gap)
                put(i, y)
                put(i + gap, x)
            i += 1
        gap = 0 if gap == 1 else (gap + 1) // 2
